        }
        for(const x of d.nodes){x.children=d.nodes.filter(v=>v.parent===x.id).map(v=>v.id);x.depth=x.path.split('::').length-1;}
        for(const x of [...d.nodes].sort((a,b)=>b.depth-a.depth))if(x.children.length){for(const key of ['new','learn','review'])x[key]=d.nodes.filter(v=>v.parent===x.id).reduce((s,v)=>s+v[key],0);}
        demoSave();return {ok:true,id:created};
      }
      if(action==='study'||action==='study_now'){d.profile.last_studied=data.id;demoSave();state.profile.last_studied=data.id;}
      const messages={study_now:'The installed add-on starts native Anki review for this lecture only. Anki’s scheduling and normal answer hooks still apply.',study:'The installed add-on opens only this selected deck in Anki’s native study overview. The reviewer controls follow your palette. Anki retains its card rendering, media, scheduling and gamification hooks.',browse:'The installed add-on opens Anki’s card browser. This preview contains no actual flashcards.',options:'The installed add-on opens Anki’s own deck options.',import:'The installed add-on opens Anki’s normal Import dialog. New decks observed afterward appear under Recently added.',add:'The installed add-on opens Anki’s native Add Cards window.',stats:'The installed add-on opens your real Anki statistics. The preview does not fabricate study history.',website:'Made by Daedalus Works · daedalusworks.net. In Anki, this opens the website in your browser.'};
      openDialog('preview-action',{message:messages[action]});return true;
    }
    nativeWidgets=window.AtelierNativeWidgets?.create({
      state,shadow,host,esc,icon,btn,ib,scope,now,preview:!!boot.preview,onigiri:()=>!!boot.integrations?.onigiri,
      openDialog,closeDialog,renderDialog,updatePref,render,announce,busy:busyDialog,reload:load,
      original:openProvider,
      progress:scopeId=>boot.preview?Promise.resolve(demoProgress(scopeId,7)):request('study_progress',{scope:scopeId,days:7})
    });
    home=window.AtelierSharedHome?.create({
      version:boot.version,state:()=>state,onigiri:()=>!!boot.integrations?.onigiri,
      tokens:()=>Object.fromEntries(['text','muted','accent','panel','line','raised','hover','scheme'].map(k=>[k,getComputedStyle(host).getPropertyValue('--'+k).trim()])),
