function inboxResults(){const ds=visibleDrafts(),pages=Math.max(1,Math.ceil(ds.length/25));S.draftPage=Math.min(S.draftPage,pages-1);const rows=ds.slice(S.draftPage*25,(S.draftPage+1)*25),selected=ds.filter(d=>S.selectedDrafts.has(d.id)).length;
