function draftsPage(){return `<div class="page-heading"><div><div class="eyebrow">Saved locally · not yet in Anki</div><h1>Drafts & approval.</h1><p>Find unfinished cards across your projects. Open a draft to edit it, or inspect a selected batch before adding anything to Anki.</p></div>${B('nav','Create cards','plus','primary','data-view="studio"')}</div><div class="ws-draft-filters"><label class="field">Find a draft<input type="search" aria-label="Search unapproved drafts" data-input="draft-query" value="${E(S.draftQuery)}" placeholder="Question, answer or project…"></label><label class="field">Project<select data-change="draft-project">${option('all','All projects',S.draftProject)}${S.state.projects.map(p=>option(p.id,p.title,S.draftProject)).join('')}</select></label></div><div id="ws-inbox-results">${inboxResults()}</div>`;}
function importPage(){const projects=S.state.projects.filter(p=>!p.archived);if(!projects.some(p=>p.id===S.project))S.project=projects[0]?.id||null;
 return `<div class="page-heading"><div><div class="eyebrow">A source is not a deck package</div><h1>Bring your material.</h1><p>Import a document or image into a local source project, then write questions or draw masks beside the original. Nothing is added to Anki until you approve it.</p></div></div><section class="ws-import-card panel">${projects.length?`<label class="field">Keep it in this project<select data-change="import-project">${projects.map(p=>option(p.id,p.title,S.project)).join('')}</select><small>This chooses where original files and drafts are kept; choose the destination Anki deck when drafting.</small></label><div class="ws-import-choices">${B('import-file',I('file',26)+'<strong>Choose files</strong><small>PDF · PowerPoint · Word · images · text · CSV/TSV</small>','','ws-import-choice')}${B('paste-source',I('text',26)+'<strong>Paste text</strong><small>Keep the passage and optional reference link</small>','','ws-import-choice')}${B('paste-image',I('media',26)+'<strong>Paste image</strong><small>Use a copied screenshot or diagram</small>','','ws-import-choice')}</div><div class="row wrap">${B('new-project','New project instead','plus','small')}${B('nav','Sources & projects','library','quiet small','data-view="library"')}</div>`:empty('Create a project for these sources.','Give your material a name. You will return here to choose files, paste text or paste an image.',B('new-project','Create source project','plus','primary'),false)}<p class="fine ws-import-note">Office files provide extracted text and embedded figures, not guaranteed original page layout. A matching PDF can preserve slide layout. To import an Anki deck package, return to Study desk → Anki tools → Import.</p></section>`;}
function libraryPage(){const all=S.state.projects,unapproved=S.state.drafts.filter(x=>x.status!=='committed').length;const ps=all.filter(p=>(S.libraryFilter==='all'||S.libraryFilter==='archived'&&p.archived||S.libraryFilter==='active'&&!p.archived)&&`${p.title} ${p.description}`.toLowerCase().includes(S.libraryQuery.toLowerCase()));
 return `<div class="page-heading"><div><div class="eyebrow">Your ideas, beautifully in place</div><h1>${S.data.integrated?'Sources & projects.':'The Living Library.'}</h1><p>A home for what you’re learning. Open a volume, find the source, and shape your next useful card.</p></div>${B('new-project','New project','plus','primary')}</div><div class="summary-strip">${[[all.filter(p=>!p.archived).length,'open projects','book'],[S.state.sources.length,'sources collected','source'],[unapproved,'drafts to shape','pen'],[new Set(S.state.links.map(l=>l.note_id)).size,'notes connected','layers']].map(([n,l,i])=>`<div class="summary-number"><strong>${n}</strong>${I(i)}<span>${l}</span></div>`).join('')}</div><div class="toolbar"><div class="tabs" role="tablist" aria-label="Library projects">${[['active','On my desk'],['archived','Archived'],['all','All volumes']].map(([k,l])=>B('library-tab',l,'','',`role="tab" data-value="${k}" aria-selected="${S.libraryFilter===k}"`)).join('')}</div><div class="row"><input class="filter-inline" type="search" data-input="library-query" aria-label="Find a project" placeholder="Find a project…" value="${E(S.libraryQuery)}"><div class="view-switch" role="group" aria-label="Library presentation">${IB('library-view','Living shelf','library',`data-value="shelf" aria-pressed="${!S.libraryList&&S.state.settings.living_library}"`)}${IB('library-view','List view','list',`data-value="list" aria-pressed="${S.libraryList||!S.state.settings.living_library}"`)}</div></div></div><div id="ws-library-results">${projectBooks(ps)}</div><div class="library-bottom"><section><div class="section-heading" style="margin-top:0"><h2>A little forward.</h2><small>Project activity, not mastery</small></div>${S.state.events.slice(0,4).map(e=>`<div class="activity-row">${I(eventIcon(e.action))}<span>${E(eventLabel(e.action))}</span><time>${when(e.at)}</time></div>`).join('')||'<p class="fine">As you collect sources, prepare cards, and resolve repairs, your progress will appear here.</p>'}</section><section class="library-note">${I('leaf')}<h3>Make room for the right cards.</h3><p class="fine">Find what you already own before making more. Keep the source close. A finished volume means its cards are prepared—not that its material is learned.</p>${B('nav','Find existing material','arrow','text-btn','data-view="find"')}</section></div>`;
}
function eventLabel(a){return ({project_saved:'A project was shaped.',source_added:'A new source joined the library.',source_updated:'A source received a new edition.',notes_added:'Approved drafts became Anki notes.',cards_committed:'Approved drafts became Anki notes.',batch_edited:'A reviewed batch edit was applied.',note_edited:'A card received a considered edit.',batch_applied:'A reviewed batch change was applied.',repair_resolved:'A repair was resolved.',repair_dismissed:'A suggestion was reviewed and dismissed.',workspace_imported:'A library archive was imported.'})[a]||String(a).replaceAll('_',' ');}
function eventIcon(a){return a.startsWith('source')?'source':a.startsWith('repair')?'checkcircle':a.startsWith('note')?'layers':'book';}
function projectBooks(ps){if(!ps.length)return empty(S.libraryQuery?'No volume by that name.':S.libraryFilter==='archived'?'Nothing shelved away.':'Every library starts with a volume.',S.libraryQuery?'Try a shorter title or clear your project search.':S.libraryFilter==='archived'?'Archive a finished project to keep your current desk clear. Its sources and cards stay intact.':'Give a subject, course, or personal project a home. Its sources, drafts, and useful cards will stay together.',B('new-project','Bind your first project','plus','primary'),true);
 const list=S.libraryList||!S.state.settings.living_library;
 return list?`<div class="project-list">${ps.map(p=>`<article class="project-list-item"><div class="mini-binding" data-cover="${p.cover}">${ART.motif(p.cover)}</div>${B('open-project',`<div><h3>${E(p.title)}</h3><p class="fine">${count(p.sources,'source')} · ${count(p.drafts,'draft')} · ${count(p.notes,'connected note')}</p></div>`,'','project-open',`data-id="${p.id}"`)}<span class="pill">${stageLabel(p)}</span>${IB('edit-project','Project settings','more',`data-id="${p.id}"`)}</article>`).join('')}</div>`:`<div class="shelf-grid">${ps.map(p=>`<article class="folio">${B('open-project',book(p),'','book-open',`data-id="${p.id}" aria-label="Open ${E(p.title)}"`)}<div class="folio-caption"><h3 title="${E(p.title)}">${E(p.title)}</h3><div class="row between"><span class="pill ${p.stage==='prepared'?'accent':''}">${p.stage==='prepared'?I('check',10):'<i class="dot"></i>'}${stageLabel(p)}</span>${B('edit-project','Details','', 'text-btn',`data-id="${p.id}"`)}</div><div class="meta"><span>${I('source',12)}${count(p.sources,'source')}</span><span>${I('layers',12)}${count(p.notes,'note')}</span>${p.drafts?`<span>${count(p.drafts,'draft')}</span>`:''}</div></div></article>`).join('')}</div>`;}
function stageLabel(p){return p.archived?'Archived':({new:'A fresh beginning',collected:'Sources collected',shaping:'Taking shape',prepared:'Cards prepared'})[p.stage]||'A fresh beginning';}
function projectPage(){const p=project();if(!p)return empty('Choose a project.','Your sources and drafts live inside a project.',B('nav','Open the library','library','primary','data-view="library"'),true);const sources=S.state.sources.filter(s=>s.project_id===p.id),drafts=S.state.drafts.filter(d=>d.project_id===p.id&&d.status!=='committed'),links=S.state.links.filter(l=>l.project_id===p.id),notes=[...new Set(links.map(x=>x.note_id))];
 return `<div class="project-hero"><div class="mini-cover">${book(p)}</div><div><div class="eyebrow">Your ${E(coverNames[p.cover].toLowerCase())} volume · ${stageLabel(p)}</div><h1>${E(p.title)}</h1><p>${E(p.description||'A considered collection of sources, drafts, and cards. Keep the context; make each question count.')}</p><div class="row wrap">${B('studio-project','Create cards','create','primary small')}${B('import-file','Add a source','upload','small')}${notes.length?B('sprout',S.data.integrated?'Build exam plan':'Prepare an exam in Sprout','leaf','small'):''}${B('edit-project','Project details','more','quiet small',`data-id="${p.id}"`)}</div></div></div><div class="project-grid"><section><div class="section-heading" style="margin-top:0"><h2>At the source.</h2><small>${count(sources.length,'source')}</small></div><div class="panel">${sources.length?sources.map(sourceRow).join(''):empty('Keep the original close.','Import PDF, PowerPoint, Word, OpenDocument, CSV/TSV, or an image. Or paste text or a screenshot. Workshop keeps a local copy and remembers its version.',B('paste-source','Paste a passage','text','primary small')+B('import-file','Choose files','upload','small'))}</div>${sources.length?`<div class="row wrap" style="margin-top:12px">${B('paste-source','Paste a passage','text','text-btn')}${B('import-file','Import files','upload','text-btn')}${B('capture-guide','Capture from your browser','globe','text-btn')}</div>`:''}<div class="section-heading"><h2>Connected cards.</h2><small>${count(notes.length,'note')}</small></div>${notes.length?`<div class="panel"><p class="fine">These are links to your original Anki notes, not duplicate cards. Source versions and citations remain inspectable.</p><div class="row wrap" style="margin-top:14px">${B('browse-project','Browse project notes','layers','small')}</div><div class="stack" style="margin-top:16px">${notes.slice(0,8).map(n=>{const l=links.find(x=>x.note_id===n),source=S.state.sources.find(s=>s.id===l.source_id);return `<div class="row between"><span class="fine">${E(source?.title||'Collection note')} ${source?'· page '+l.page:''}</span>${B('open-note','Inspect','eye','text-btn',`data-nid="${n}"`)}</div>`;}).join('')}</div>${notes.length>8?'<p class="micro" style="margin-top:12px">Showing eight links. Browse project notes for the complete selection.</p>':''}</div>`:notice('Nothing linked yet. Approve a draft or find and link an existing note; its original scheduling is preserved.')}</section><section><div class="section-heading" style="margin-top:0"><h2>On the worktable.</h2><small>${count(drafts.length,'draft')}</small></div>${drafts.length?`${drafts.slice(0,20).map(draftRow).join('')}<div class="row wrap" style="margin-top:12px">${B('approve-project','Review & add drafts','check','primary small')}${B('studio-project','Open the studio','arrow','small')}</div>${drafts.length>20?'<p class="fine">Open the studio for the complete draft tray.</p>':''}`:empty('One clear question at a time.','Select a source passage or begin with a question of your own. Nothing reaches Anki until you approve it.',B('studio-project','Open Card Studio','create','primary small'))}<div class="milestone">${I(p.stage==='prepared'?'checkcircle':'book')}<div><h3>${p.stage==='prepared'?'A volume, prepared.':'From collected to considered.'}</h3><p class="fine">${p.stage==='prepared'?'Your linked notes are in Anki and there are no unfinished drafts. Learning continues in the reviewer.':'Source collection and card preparation are visible milestones. They do not award mastery or exam-readiness points.'}</p></div></div><div class="row wrap" style="margin-top:18px">${B('export-drafts','Export draft text','download','text-btn')}${B('archive-project',p.archived?'Restore to desk':'Archive this project','archive','text-btn')}</div></section></div>`;
}
function sourceRow(s){return `<div class="source-row"><div class="source-stamp">${I(s.kind==='pdf'?'file':['png','jpg','jpeg','webp'].includes(s.kind)?'media':'text')}</div><div class="source-copy"><h3>${E(s.title)}</h3><p class="fine">${s.kind.toUpperCase()} · ${count(s.page_count,'page')} · ${when(s.updated)}</p><div class="row wrap">${B('open-source','Read & create','arrow','text-btn',`data-id="${s.id}"`)}${B('source-diff','Edition history','refresh','text-btn',`data-id="${s.id}"`)}</div></div>${IB('update-source','Import a revised edition','upload',`data-id="${s.id}"`)}</div>`;}
function draftRow(d){return `<article class="draft-item"><input type="checkbox" aria-label="Select draft ${E(d.front||'Untitled question')}" data-check="draft" data-id="${d.id}"${S.selectedDrafts.has(d.id)?' checked':''}><div class="draft-copy"><h3>${E(d.front||'Question not written yet')}</h3><p>${E(d.back||d.context||'Continue shaping this draft in Card Studio.')}</p><div class="row wrap"><span class="pill">${E(styles.find(x=>x[0]===d.kind)?.[1]||'Question')}</span>${d.origin==='ai'?'<span class="pill warn">'+(d.verified?'AI · reviewed':'AI · needs review')+'</span>':''}${B('edit-draft','Open','arrow','text-btn',`data-id="${d.id}"`)}${B('discard-draft','Discard','trash','text-btn draft-delete',`data-id="${d.id}" aria-label="Discard this unapproved draft"`)}</div></div></article>`;}
function studioPage(){if(!S.project&&S.state.projects.length)S.project=S.state.projects.find(p=>!p.archived)?.id||S.state.projects[0].id;
 if(!project())return `<div class="page-heading"><div><div class="eyebrow">Source → question → understanding</div><h1>Your Card Studio.</h1></div></div>`+empty('Give your cards a home first.','A project keeps source passages, drafts, and existing cards together. Choose its title and binding to begin.',B('new-project','Create a project','plus','primary'),true);
 const d=S.draft,sources=S.state.sources.filter(s=>s.project_id===S.project),drafts=S.state.drafts.filter(x=>x.project_id===S.project&&x.status!=='committed');
 return `<div class="workbench-head"><div><div class="eyebrow">Read closely. Ask clearly.</div><h1>Card Studio.</h1></div><div class="row wrap"><select data-change="studio-project" aria-label="Current project">${S.state.projects.map(p=>option(p.id,p.title,S.project)).join('')}</select>${IB('new-draft','Start a new draft','plus')}</div></div>${studioWorkflow(d,drafts.length)}<div class="workbench"><section class="source-pane" aria-label="Original source"><div class="pane-header"><div class="row"><span class="eyebrow">The source</span>${B('import-file','Import','upload','quiet small','style="margin-left:auto"')}${B('paste-source','Paste text','text','quiet small')}${B('paste-image','Paste image','media','quiet small')}</div>${sources.length?`<select data-change="studio-source" aria-label="Source document">${option('','Choose a source',S.source?.source.id||'')}${sources.map(s=>option(s.id,s.title,S.source?.source.id)).join('')}</select>`:''}${S.source?`<div class="source-navigation">${IB('page-prev','Previous source page','arrowleft')}<input type="number" data-change="page-number" aria-label="Source page" min="1" max="${S.source.version.pages.length}" value="${S.page}"><span>of ${S.source.version.pages.length}</span>${IB('page-next','Next source page','arrow')}<select data-change="source-version" aria-label="Source edition">${S.source.versions.map(v=>option(v.id,'Edition '+v.ordinal,S.source.version.id)).join('')}</select></div>`:''}</div><div class="source-body" id="ws-source-body">${sourceBody()}</div><div class="selected-passage" id="ws-selection" ${S.selection?'':'hidden'}><strong>Selected passage</strong><span>${E(S.selection)}</span></div><div class="source-toolbar">${B('mask-source','Mask this page','crop','primary small',!S.pageDoc?.image?'disabled':'')}${B('use-passage','Use selected passage','bookmark','small',!S.source?'disabled':'')}${B('toggle-source-mode',S.sourceMode==='text'?'Page view':'Extracted text',S.sourceMode==='text'?'eye':'text','small',!S.source?'disabled':'')}${B('crop-mode',S.cropping?'Cancel selection':'Select image region','crop','small',!S.pageDoc?.image?'disabled':'')}${S.crop?B('capture-crop','Use selected region','check','primary small'):''}${S.source&&['pptx','odp'].includes(S.source.source.kind)?B('pdf-layout','Attach PDF layout','file','quiet small'):''}${S.source?.version.blob?B('open-original','Open original','external','quiet small'):''}</div></section><section class="editor-pane" aria-label="Card draft">${d?draftEditor(d):`<div class="editor-top"><div class="eyebrow">The question</div></div>${empty('A blank page, with purpose.','Start from your source, or write your own precise question. Drafts stay local until you approve them.',B('new-draft','Start a draft','plus','primary small'))}`}</section></div>${drafts.length?`<section class="draft-shelf"><div class="section-heading" style="margin-top:0"><div><h2>Your draft tray.</h2><small>Local drafts · not yet in Anki</small></div><div class="row wrap">${B('select-all-drafts','Select all','check','quiet small')}${B('approve-selected','Review & add','arrow','primary small')}</div></div><div class="tray-list">${drafts.map(draftRow).join('')}</div></section>`:''}`;
}
function sourceBody(){if(!S.source)return empty('Keep the source in sight.','Open a source from this project or paste a passage. Text selection becomes a citation; image regions can go to Anki’s native occlusion editor.',B('paste-source','Paste a passage','text','small'),false);
 if(!S.pageDoc)return loading('Opening this page…');
 const d=S.pageDoc;if(S.sourceMode==='page'&&d.image)return `<div class="source-visual ${S.cropping?'crop-mode':''}" id="ws-source-visual"><img src="${E(d.image)}" alt="Original page ${S.page} of ${E(S.source.source.title)}" draggable="false">${S.crop?cropRect():''}${S.cropping?'<div class="crop-tip">Drag a rectangle inside the page.</div>':''}</div>${sourceExtras(d)}`;
 return `${d.visual_unavailable?notice(d.message):''}${!d.text?notice('This page has no extractable text. Page view preserves the image; no text has been guessed or silently transcribed.')+B('toggle-source-mode','View the original page','eye','small'): `<article class="source-paper" id="ws-source-paper" data-label="${E(S.source.source.title)} · ${S.page}">${E(d.text)}</article>`}${S.source.version.metadata?.extraction_note?`<p class="fine" style="margin-top:12px">${E(S.source.version.metadata.extraction_note)}</p>`:''}${sourceExtras(d)}`;
}
function sourceExtras(d){return `${d.hidden_slide?notice('Hidden slide in the original presentation. Included here so no source material silently disappears.'):''}${d.notes?`<details class="source-notes"><summary>Speaker notes</summary><div class="pre">${E(d.notes)}</div></details>`:''}${d.assets?.length?`<section class="figure-gallery"><h3>Embedded figures · ${d.asset_count||d.assets.length}</h3><p class="micro">Original raster images, not reconstructed slide layouts.</p><div class="figure-list">${d.assets.map((a,i)=>`<article class="figure-tile"><img ${a.image?`src="${E(a.image)}"`:`data-figure-index="${i}"`} alt="${E(a.label)}" loading="lazy" decoding="async"><span class="figure-loading" ${a.image?'hidden':''} role="status">Loading figure…</span><p>${E(a.label)}</p><div class="row wrap">${B('mask-asset','Mask figure','crop','small',`data-index="${i}"`)}${B('attach-asset','Use image','plus','text-btn',`data-index="${i}"`)}</div></article>`).join('')}</div>${d.asset_count>d.assets.length?notice('The first 40 figures are shown here. Use the original document to inspect the remainder.'):''}</section>`:''}`;}
function cropRect(){return `<div class="crop-selection" style="left:${S.crop.x*100}%;top:${S.crop.y*100}%;width:${S.crop.w*100}%;height:${S.crop.h*100}%"></div>`;}
function draftEditor(d){const src=S.state.sources.find(x=>x.id===d.source_id),models=S.data.catalog.models.filter(m=>!m.occlusion);
 return `<div class="editor-top"><div class="eyebrow">The question</div><span class="pill">${d.origin==='ai'?'AI-assisted · author approval required':'Authored by you'}</span></div><div class="style-switch" role="group" aria-label="How to test this idea">${styles.map(([k,l,i])=>B('card-style',l,i,'',`data-value="${k}" aria-pressed="${d.kind===k}"`)).join('')}</div>${d.kind==='occlusion'?`<div class="mask-summary"><strong>${d.masks?.length||0} masks · ${new Set((d.masks||[]).map(m=>m.group)).size} questions</strong>${B('edit-mask-draft','Open Mask Studio','crop','primary small')}</div>`:''}<div class="editor-fields"><label class="field">${d.kind==='cloze'?'Text with a hidden phrase':'Question'}<textarea data-draft="front" maxlength="40000" aria-label="Draft question">${E(d.front)}</textarea>${d.kind==='cloze'?`<small>Select text above, then ${B('make-cloze','Hide the selected phrase','cloze','text-btn')} Each new cloze number creates a separate card.</small>`:''}</label><label class="field">${d.kind==='occlusion'?'Extra explanation (optional)':d.kind==='cloze'?'Extra explanation on the answer side':'Answer'}<textarea data-draft="back" maxlength="40000" aria-label="Draft answer">${E(d.back)}</textarea></label>${d.kind==='compare'?'<p class="fine">State the distinguishing feature, not just two separate definitions. Confirm both ideas against their sources.</p>':d.kind==='sequence'?'<p class="fine">Name the starting conditions and why the order matters. Split unrelated steps into separate questions.</p>':d.kind==='application'?'<p class="fine">Write the situation, the decision, and the reason. Workshop does not invent clinical cases or certify their answers.</p>':''}<div class="form-grid"><label class="field">Destination deck<select data-draft="deck_id">${S.data.catalog.decks.map(x=>option(x.id,x.name,d.deck_id)).join('')}</select>${B('find-destination','Find or sort decks','search','text-btn')}</label><label class="field">Tags<input data-draft="tags" aria-label="Draft tags" value="${E(d.tags.join(' '))}" maxlength="4000"></label></div></div><details ${d.media.length?'open':''}><summary>Images & audio${d.media.length?' · '+d.media.length:''}</summary><div class="media-chips">${d.media.map((m,i)=>`<div class="media-chip">${I(/\.(mp3|wav|ogg)$/.test(m.blob)?'volume':'media')}<span>${E(m.alt||('Attachment '+(i+1)))} · ${m.side}</span>${IB('remove-attachment','Remove this attachment from the draft','close',`data-index="${i}"`)}</div>`).join('')}</div><div class="row wrap" style="margin-top:10px">${B('attach-file','Attach image / audio','upload','small')}${B('nav','Reuse collection media','media','small','data-view="media"')}${B('native','Native audio tools','volume','quiet small','data-native="tts"')}${d.media.some(m=>/\.(png|jpg|jpeg|webp)$/.test(m.blob))?B('edit-mask-draft','Mask image here','crop','small')+B('native-occlusion','Native mask tools','external','quiet small'):''}</div><p class="fine" style="margin-top:9px">Attachments are copied, never replaced globally. Mask Studio saves native Image Occlusion notes. Native mask tools remain available separately.</p></details><details><summary>Source, explanation & note type</summary><div class="stack"><label class="field">Context / explanation<textarea data-draft="context" maxlength="20000">${E(d.context)}</textarea></label><label class="field">Source passage<textarea data-draft="quote" maxlength="20000">${E(d.quote)}</textarea><small>${src?`${E(src.title)} · page ${d.page}. This citation is checked as text, not certified as fact.`:'No source linked. Select a passage or link this draft to a source before claiming source support.'}</small></label><label class="field">Note type<select data-draft="model_id"${d.kind==='occlusion'?' disabled':''}>${option(0,d.kind==='occlusion'?'Anki · Image Occlusion':d.kind==='cloze'?'Workshop · Cloze (portable)':'Workshop · Recall (portable)',d.model_id)}${d.kind==='occlusion'?'':models.map(m=>option(m.id,m.name,d.model_id)).join('')}</select><small>Existing note types are not changed. Map fields explicitly when choosing your own.</small></label><div id="ws-field-mapping">${fieldMapping(d)}</div></div></details>${d.origin==='ai'?`<label class="check"><input type="checkbox" data-draft="verified"${d.verified?' checked':''}><span>I checked the question, answer, and citation against the source.<small>AI output is a suggestion. A quote match alone does not establish factual correctness.</small></span></label>`:''}<div class="row wrap">${B('find-matches','Find existing cards first','search','text-btn')}${B('ai-drafts','Source-grounded suggestions','wand','text-btn')}</div><div id="ws-matches">${matchingRows()}</div><div class="editor-foot"><span class="save-indicator" id="ws-save-state">${S.dirty?'Unsaved changes':d.id?'Saved locally':'New local draft'}</span><div class="row">${B('preview-draft','Preview','eye','small')}${B('save-draft','Save draft','check','primary small')}</div></div>`;
}
function bindDestinations(){
 root.addEventListener('input',e=>{if(e.target.id==='ws-destination-query'){destinationQuery=e.target.value;$('#ws-destination-results').innerHTML=destinationRows();}});
 root.addEventListener('change',e=>{if(e.target.id==='ws-destination-sort'){destinationSort=e.target.value;$('#ws-destination-results').innerHTML=destinationRows();}});
}
function destinationRows(){
 const q=destinationQuery.normalize('NFKD').replace(/[\u0300-\u036f]/g,'').toLocaleLowerCase(),compare=new Intl.Collator(undefined,{numeric:true,sensitivity:'base'});
 const matches=destinationOptions.filter(d=>d.name.normalize('NFKD').replace(/[\u0300-\u036f]/g,'').toLocaleLowerCase().includes(q));
 matches.sort((a,b)=>(destinationSort==='active'?Number(!!b.active)-Number(!!a.active):0)||compare.compare(a.name,b.name));
 return `<p class="fine">${matches.length} matches. ${matches.length>80?'Refine your search to show a specific deck.':''}</p>${matches.slice(0,80).map(d=>B('pick-destination',`<span><strong>${E(d.name.replaceAll('::',' › '))}</strong><small>${d.active?'Active class':'Anki deck'}</small></span>`,'folder','ws-destination',`data-id="${E(d.id)}"`)).join('')||'<p>No matching decks.</p>'}`;
}
function fieldMapping(d){if(d.kind==='occlusion')return '';const m=S.data.catalog.models.find(x=>x.id===Number(d.model_id));if(!m)return '';return `<div class="mapping-grid">${[['front','Question field'],['back','Answer field'],['context','Explanation field'],['source','Citation field']].map(([k,l])=>`<label class="field">${l}<select data-mapping="${k}">${option('','Choose / omit',d.mapping[k]||'')}${m.fields.map(f=>option(f,f,d.mapping[k])).join('')}</select></label>`).join('')}</div>`;}
function matchingRows(){if(!S.matchRan)return '';return `<div class="matching"><div class="row between"><h3>Existing material</h3><span class="micro">Related ≠ duplicate</span></div>${S.matches.length?S.matches.slice(0,5).map(n=>`<article class="match-row"><h3>${E(n.front||n.model)}</h3><p>${E(n.why)}</p><div class="row wrap">${B('preview-note','Preview','eye','text-btn',`data-nid="${n.id}"`)}${B('link-existing','Use this existing note','source','text-btn',`data-nid="${n.id}"`)}</div></article>`).join(''):'<p class="fine" style="margin-top:10px">No matching wording was found in the searched candidate window. This is not proof that no equivalent concept exists.</p>'}</div>`;}
function afterStudio(){if(S.source&&!S.pageDoc)fetchPage().catch(e=>toast(e.message,true));bindCrop();loadFigures();}
function rememberPage(key,result){
 const size=JSON.stringify(result).length*2;if(size>24*1024*1024)return;
 if(pageMemory.has(key)){pageBytes-=pageMemory.get(key).size;pageMemory.delete(key);}
 while(pageMemory.size&&(pageBytes+size>24*1024*1024||pageMemory.size>=8)){const k=pageMemory.keys().next().value;pageBytes-=pageMemory.get(k).size;pageMemory.delete(k);}
 pageMemory.set(key,{result,size});pageBytes+=size;
}
function loadPage(version,page){
 const key=[version.id,version.revision,version.updated,version.metadata?.visual_pdf||'',page,1600].join(':');
 if(pageMemory.has(key)){const item=pageMemory.get(key);pageMemory.delete(key);pageMemory.set(key,item);return Promise.resolve(item.result);}
 if(pageRequests.has(key))return pageRequests.get(key);
 const job=request('page',{version_id:version.id,page,width:1600}).then(r=>{rememberPage(key,r);return r;}).finally(()=>pageRequests.delete(key));
 pageRequests.set(key,job);return job;
}
function drainFigures(){
 while(figureActive<2&&figureQueue.length){
  const {img,asset,token,generation}=figureQueue.shift();
  if(!img.isConnected||token!==pageToken||generation!==figureGeneration)continue;
  figureActive++;
  request('figure_preview',{blob:asset.blob,width:360}).then(r=>{
   if(!img.isConnected||token!==pageToken||generation!==figureGeneration)return;
   img.onload=()=>{img.nextElementSibling?.setAttribute('hidden','');};
   img.onerror=()=>{if(img.nextElementSibling)img.nextElementSibling.textContent='Preview unavailable · use original';};
   img.src=r.image;
  }).catch(()=>{if(img.isConnected&&generation===figureGeneration&&img.nextElementSibling)img.nextElementSibling.textContent='Preview unavailable · use original';})
   .finally(()=>{figureActive--;drainFigures();});
 }
}
function loadFigures(){
 figureObserver?.disconnect();const generation=++figureGeneration;figureQueue=[];
 const token=pageToken,doc=S.pageDoc;
 const enqueue=img=>{const asset=doc?.assets[Number(img.dataset.figureIndex)];if(asset)figureQueue.push({img,asset,token,generation});};
 const images=$$('[data-figure-index]');
 if(!window.IntersectionObserver){images.forEach(enqueue);drainFigures();return;}
 figureObserver=new IntersectionObserver(items=>{for(const item of items)if(item.isIntersecting){figureObserver.unobserve(item.target);enqueue(item.target);}drainFigures();},{root:$('#ws-source-body'),rootMargin:'160px'});
 images.forEach(img=>figureObserver.observe(img));
}
async function originalAsset(asset){
 if(!asset)throw new Error('Choose a figure on the current page.');
 if(!asset.preview_pending)return asset;
 const token=pageToken,source=S.source?.version.id,page=S.page;
 const result=await request('image',{blob:asset.blob});
 if(token!==pageToken||source!==S.source?.version.id||page!==S.page)throw new Error('The source changed while the image was loading. Choose the figure on the current page.');
 return {...asset,image:result.image,preview_pending:false};
}
async function fetchPage(){if(!S.source)return;const token=++pageToken,version=S.source.version,vid=version.id,page=S.page;const result=await loadPage(version,page);if(token!==pageToken||S.source?.version.id!==vid||S.page!==page)return;S.pageDoc=result;if(S.sourceMode==='page'&&!result.image)S.sourceMode='text';if(S.view==='studio'&&$('#ws-source-body')){$('#ws-source-body').innerHTML=sourceBody();bindCrop();loadFigures();for(const action of ['crop-mode','mask-source']){const t=$('[data-action="'+action+'"]');if(t)t.disabled=!result.image;}}}

async function openSource(id,versionId='',page=1){await flushDraft();S.source=await request('source',{id,version_id:versionId});S.project=S.source.source.project_id;S.page=Math.min(page,S.source.version.pages.length);S.pageDoc=null;S.selection='';S.crop=null;S.cropping=false;S.sourceMode=(['pdf','png','jpg','jpeg','webp'].includes(S.source.source.kind)||S.source.version.metadata?.visual_pdf)?'page':'text';S.view='studio';if(!S.draft||S.draft.project_id!==S.project)createDraftObject();render();scrollTop();}
function clearSourceContext(){figureGeneration++;figureObserver?.disconnect();figureQueue=[];pageToken++;S.source=null;S.pageDoc=null;S.page=1;S.selection='';S.crop=null;S.cropping=false;}
function createDraftObject(kind='question'){S.draft={project_id:S.project,source_id:'',version_id:'',page:1,front:'',back:'',context:'',quote:'',kind,deck_id:S.data.current_deck||S.data.catalog.decks[0]?.id||1,model_id:0,mapping:{},tags:[],media:[],masks:[],hide_others:true,origin:'manual',verified:false};S.dirty=false;S.editVersion++;S.matches=[];S.matchRan=false;}
async function newDraft(kind='question'){await flushDraft();if(!S.project)return projectDialog();createDraftObject(kind);S.view='studio';render();$('[data-draft="front"]')?.focus();}
function markDirty(){const wasDirty=S.dirty;S.dirty=true;S.editVersion++;if(!wasDirty)request('dirty',{value:true}).catch(()=>{});clearTimeout(saveTimer);const el=$('#ws-save-state');if(el)el.textContent='Saving locally…';saveTimer=setTimeout(()=>saveDraft(false).catch(e=>{const el=$('#ws-save-state');if(el)el.textContent='Not saved';toast(e.message,true);}),900);}
async function saveDraft(explicit=false){if(!S.draft)return;if(savePromise){await savePromise;if(S.dirty)return saveDraft(explicit);return S.draft;}if(!S.dirty&&S.draft.id)return S.draft;
 const old=S.draft,stamp=S.editVersion,payload={...old,review_confirm:old.verified};clearTimeout(saveTimer);
 savePromise=request('save_draft',payload).then(result=>{upsert('drafts',result);if(S.draft===old){if(S.editVersion===stamp){S.draft=result;S.dirty=false;request('dirty',{value:false}).catch(()=>{});}else{S.draft={...result,...old,id:result.id,revision:result.revision};S.dirty=true;request('dirty',{value:true}).catch(()=>{});}const el=$('#ws-save-state');if(el)el.textContent=S.dirty?'Saving locally…':'Saved locally';}return result;});
 try{const out=await savePromise;if(explicit)toast('Draft saved locally. It has not been added to Anki.');return out;}finally{savePromise=null;}
}
async function flushDraft(){clearTimeout(saveTimer);if(savePromise)await savePromise;if(S.draft&&S.dirty)await saveDraft();}
async function usePassage(){if(!S.source)throw new Error('Choose a source first.');if(!S.selection.trim())throw new Error('Select a passage in Extracted text first. For an image-only page, capture its region instead.');if(!S.draft)createDraftObject();Object.assign(S.draft,{source_id:S.source.source.id,version_id:S.source.version.id,page:S.page,quote:S.selection});if(!S.draft.front&&S.draft.kind==='cloze')S.draft.front=S.selection;markDirty();render();toast('Source passage attached. Write the question you want to test.');}
function bindCrop(){const v=$('#ws-source-visual');if(!v||!S.cropping)return;let start=null;const position=e=>{const b=v.getBoundingClientRect();return {x:Math.min(1,Math.max(0,(e.clientX-b.left)/b.width)),y:Math.min(1,Math.max(0,(e.clientY-b.top)/b.height))};};v.addEventListener('pointerdown',e=>{if(e.button!==0)return;start=position(e);v.setPointerCapture(e.pointerId);S.crop=null;e.preventDefault();});v.addEventListener('pointermove',e=>{if(!start)return;const p=position(e);S.crop={x:Math.min(start.x,p.x),y:Math.min(start.y,p.y),w:Math.abs(p.x-start.x),h:Math.abs(p.y-start.y)};v.querySelector('.crop-selection')?.remove();v.insertAdjacentHTML('beforeend',cropRect());});v.addEventListener('pointerup',e=>{if(!start)return;start=null;v.releasePointerCapture(e.pointerId);if(!S.crop||S.crop.w<.01||S.crop.h<.01){S.crop=null;toast('Draw a larger region inside the page.');}render();});}
function findPage(){const q=S.search;return `<div class="page-heading"><div><div class="eyebrow">Less duplication. More connection.</div><h1>Find what you already know.</h1><p>Search original Anki notes and your source library. Similar wording is a clue—not proof that two cards mean the same thing.</p></div></div><form id="ws-search-form" class="search-form"><div class="search-input">${I('search')}<input data-input="search-query" type="search" value="${E(q.query)}" aria-label="Search cards and sources" placeholder="A concept, phrase, or Anki search…"></div><select data-change="search-deck" aria-label="Limit search to a deck">${option(0,'All decks',q.deck_id)}${S.data.catalog.decks.map(d=>option(d.id,d.name,q.deck_id)).join('')}</select>${B('run-search','Search','arrow','primary','type="submit"')}<label class="check"><input type="checkbox" data-check="native-search"${q.mode==='anki'?' checked':''}><span>Use Anki’s search syntax</span></label></form><div class="toolbar"><div class="tabs" role="tablist" aria-label="Search scope">${[['cards','Your cards'],['sources','Source passages']].map(([k,l])=>B('search-scope',l,'','',`role="tab" data-value="${k}" aria-selected="${q.scope===k}"`)).join('')}</div><div class="row">${B('semantic','Optional semantic rerank','sparkle','text-btn',q.scope!=='cards'||!q.results.length?'disabled':'')}${B('native','Native Browser','external','text-btn','data-native="browse"')}</div></div><div id="ws-search-results">${searchResults()}</div>${S.selectedNotes.size?bulkBar():''}`;}
function searchResults(){const q=S.search;if(!q.ran)return empty('Start with a phrase you remember.','Keyword search works offline. Advanced Anki searches, source passages, and optional semantic reranking stay clearly separate.',B('search-all','Browse collection notes','layers','small'));
 if(!q.results.length)return empty('Nothing matched this search.','Try another phrase, clear the deck limit, or use native Anki syntax. A missing keyword match does not mean your collection lacks the concept.',B('native','Open Anki Browser','external','small','data-native="browse"'));
 if(q.scope==='sources')return `<div class="results-heading"><span>${count(q.results.length,'matching source passage')} · exact local text, ranked by wording</span></div><div class="note-results">${q.results.map(r=>{const src=S.state.sources.find(s=>s.id===r.source_id);return `<article class="note-row"><div class="source-stamp">${I('source')}</div><div class="note-copy"><h3>${E(src?.title||'Source passage')} · page ${r.page}</h3><p>${E(r.text)}</p><div class="note-metadata"><span class="micro">${E(r.why)}</span></div></div>${B('open-search-source','Read','arrow','small',`data-id="${r.source_id}" data-version="${r.version_id}" data-page="${r.page}"`)}</article>`;}).join('')}</div>`;
 return `<div class="results-heading"><span>${count(q.total,'note')+' matching Anki’s candidate search'} · ${q.results.length} shown${q.candidate_limit?' · ranked '+q.candidate_limit+' candidates':''}</span><span>Select 2–3 notes to compare</span></div><div class="note-results">${q.results.map(noteRow).join('')}</div>${q.has_more?`<div class="row" style="justify-content:center;margin-top:18px">${B('search-next','Next candidate window','arrow','small')}</div>`:''}<p class="micro" style="margin-top:16px">Full card rendering and audio use Anki’s own Preview window. No card template scripts execute in this search list.</p>`;
}
function noteRow(n){return `<article class="note-row"><input type="checkbox" data-check="note" data-nid="${n.id}" aria-label="Select ${E(n.front||n.model)}"${S.selectedNotes.has(n.id)?' checked':''}><div class="note-copy"><h3>${E(n.front||n.model+' · media or cloze note')}</h3><p>${E(n.text.slice(n.front?.length||0).trim())}</p><div class="note-metadata"><span class="pill">${E(n.model)}</span><span class="micro">${count(n.cards.length,'card')}</span>${n.protection?.managed?'<span class="pill warn">Managed</span>':''}${n.issues?.some(i=>i.severity==='error')?'<span class="pill warn">Needs attention</span>':''}</div><div class="micro" style="margin-top:8px">${E(n.why||'Original Anki note')}</div></div><div class="note-actions">${B('preview-note','Preview','eye','small',`data-nid="${n.id}"`)}${B('open-note','Inspect & improve','pen','quiet small',`data-nid="${n.id}"`)}</div></article>`;}
function bulkBar(){return `<div class="bulk-float"><strong>${count(S.selectedNotes.size,'note')} selected</strong>${B('compare-notes','Compare ideas','compare','small',S.selectedNotes.size<2||S.selectedNotes.size>3?'disabled':'')}${B('batch-dialog','Bulk change','layers','small')}${B('link-selected','Link to project','source','small')}${B('clear-note-selection','Clear','','quiet small')}</div>`;}
function improvePage(){const open=S.state.repairs.filter(r=>S.repairFilter==='all'||r.status===S.repairFilter),s=S.scan;return `<div class="page-heading"><div><div class="eyebrow">Make the difficult cards worth the effort</div><h1>A little better, each time.</h1><p>Finish studying first. Return here to clarify a prompt, mend its source, or separate ideas that keep getting tangled.</p></div>${B('scan','Check collection','improve','primary')}</div><div class="repair-layout"><section><div class="toolbar" style="margin-top:0"><div class="tabs" role="tablist" aria-label="Repair queue">${[['open','Needs attention'],['resolved','Resolved'],['all','All activity']].map(([v,l])=>B('repair-tab',l,'','',`role="tab" data-value="${v}" aria-selected="${S.repairFilter===v}"`)).join('')}</div><span class="micro">${count(open.length,'item')}</span></div>${open.length?open.map(r=>`<article class="repair-card"><div class="repair-mark">${I(r.origin==='source'?'refresh':r.status==='resolved'?'check':'flag')}</div><div class="repair-copy"><h3>${E(r.reason)}</h3><p class="fine">${r.origin==='source'?'Source-change review':r.origin==='manual'?'Marked by you':'Collection check'} · ${when(r.created)} · ${r.status}</p><div class="row wrap">${B('repair-open','Review this note','arrow','text-btn',`data-nid="${r.note_id}" data-id="${r.id}"`)}${r.status==='open'?B('repair-resolve','Mark resolved','check','text-btn',`data-id="${r.id}"`)+B('repair-dismiss','Dismiss','close','text-btn',`data-id="${r.id}"`):B('repair-reopen','Reopen','refresh','text-btn',`data-id="${r.id}"`)}</div></div></article>`).join(''):empty(S.repairFilter==='resolved'?'The small fixes will add up.':'A clear worktable.',S.repairFilter==='resolved'?'Your reviewed repairs appear here once resolved.':'Mark “Needs attention” from a card’s context menu while reviewing, or run a collection check for technical issues and possible design problems.',B('scan','Check collection notes','improve','small'))}${s.ran?`<section class="panel" style="margin-top:24px"><div class="row between"><h2>Collection check.</h2><span class="pill">${s.complete?'Scan complete':'Partial scan'}</span></div><p class="fine" style="margin:10px 0">${s.scanned} notes inspected. Technical problems and design suggestions are different; no note has been changed.</p>${s.items.length?s.items.map(n=>`<article class="scan-result"><h3>${E(n.front||n.model)}</h3>${issueList(n.issues)}<div class="row wrap">${B('open-note','Inspect','eye','small',`data-nid="${n.id}"`)}${B('flag-scan','Add to repair queue','flag','quiet small',`data-nid="${n.id}"`)}</div></article>`).join(''):'<p class="fine">No issues were detected in this scanned portion. That is not a factual-correctness certification.</p>'}${s.cursor?B('scan-next','Check the next 250 notes','arrow','small'):''}</section>`:''}</section><aside class="repair-side"><section class="panel">${I('flag')}<h3>Catch it. Keep going.</h3><p>During a normal review, right-click the card and choose <strong>Atelier · Needs attention</strong>. The card stays where it is.</p><div class="row"><kbd>Ctrl Alt R</kbd><span class="micro">Mark the current note</span></div></section><section class="panel">${I('shield')}<h3>Edit with intent.</h3><p>A wording correction keeps the note and its cards. Splitting an idea creates new drafts; it does not make them mature or delete the original.</p><p>Managed fields and image-occlusion masks go to the native editor.</p></section>${S.state.pairs.length?`<section class="panel"><h3>Ideas to distinguish.</h3>${S.state.pairs.slice(0,5).map(p=>`<div style="margin-top:10px">${B('open-pair',E(p.label),'compare','text-btn',`data-id="${p.id}"`)}</div>`).join('')}</section>`:''}</aside></div>`;}
function mediaPage(){const m=S.media;return `<div class="page-heading"><div><div class="eyebrow">Useful images deserve to be found again</div><h1>Your visual materials.</h1><p>Find collection media, inspect its original note references, and reuse it deliberately. Nothing is deleted or replaced globally.</p></div>${B('attach-file','Import media','upload','primary')}</div><form id="ws-media-form" class="search-form"><div class="search-input">${I('search')}<input data-input="media-query" type="search" value="${E(m.query)}" aria-label="Find media by filename" placeholder="Find an image or audio filename…"></div>${B('media-search','Search','arrow','primary')}</form><div class="results-heading"><span>${m.ran?count(m.items.length,'file')+' shown':'Collection media loads when you open this page.'}</span>${B('native','Anki’s media check','shield','text-btn','data-native="check_media"')}</div>${m.items.length?`<div class="media-grid">${m.items.map(x=>`<article class="media-tile"><div class="media-thumb" data-media-thumb="${E(x.name)}">${I(/\.(mp3|ogg|wav)$/i.test(x.name)?'volume':'media')}</div><div class="media-meta"><h3>${E(x.name)}</h3><p>${(x.bytes/1024).toFixed(1)} KB · ${E(x.kind||x.name.split('.').pop())}</p><div class="row wrap">${B('media-references','References','source','text-btn',`data-name="${E(x.name)}"`)}${B('reuse-media','Use in draft','plus','text-btn',`data-name="${E(x.name)}"`)}</div></div></article>`).join('')}</div>`:m.ran?empty('No matching media files.','Search by part of a filename or import an image into a draft. Technical media checks stay with Anki.',B('attach-file','Choose an image or audio','upload','small')):loading('Finding collection media…')}${m.has_more?`<div class="row" style="margin-top:20px;justify-content:center">${B('media-next','Next files','arrow','small')}</div>`:''}`;}
function loadMediaThumbs(){mediaObserver=new IntersectionObserver(entries=>entries.forEach(entry=>{if(!entry.isIntersecting)return;const el=entry.target;mediaObserver.unobserve(el);const name=el.dataset.mediaThumb;if(/\.(mp3|wav|ogg)$/i.test(name))return;request('media_preview',{name}).then(data=>{if(el.isConnected)el.innerHTML=`<img src="${E(data.image)}" alt="${E(name)}" loading="lazy">`;}).catch(()=>{if(el.isConnected)el.innerHTML=I('warning');});}),{root:$('#ws-scroll'),rootMargin:'100px'});$$('[data-media-thumb]').forEach(el=>mediaObserver.observe(el));}
function settingsPage(){const s=S.state.settings,i=S.data.integrations;return `<div class="page-heading"><div><div class="eyebrow">Your library. Your boundaries.</div><h1>Make it feel like yours.</h1><p>Appearance, careful integrations, and a clear view of what stays local.</p></div></div><div class="settings-layout"><div><section class="settings-section"><h2>Atmosphere.</h2><p>Finished materials and restrained motion. Reading and editing always take priority.</p>${S.data.integrated&&S.data.suite_appearance?.enabled?`<div class="shared-world-note"><strong>One appearance, everywhere.</strong><p>Card Studio follows <b id="ws-shared-world-name">${E(S.data.suite_appearance.world.name)}</b>. Use the header World selector to update the home, exam planner, and creation tools together. Your draft stays open.</p></div>${settingSwitch('living_library','Dimensional project shelf','Use individual book covers for projects. List view stays available.')}`:`<div class="theme-grid">${[['night','Evening','#141b1b','#111817','#335643'],['paper','Daylight','#f3f0e7','#e9e6da','#814735'],['forest','Fern room','#10201c','#0d1c18','#4d6540'],['atelier','Follow Anki','#f3f1eb','#eae7de','#715664']].map(([k,l,bg,side,b])=>B('theme',`<span class="theme-mini" style="--mini-bg:${bg};--mini-side:${side};--mini-book:${b}"><i></i><i></i><i></i></span><span>${l}</span>`,'','theme-card',`data-value="${k}" aria-pressed="${s.theme===k}"`)).join('')}</div>${settingSwitch('living_library','Living Library shelf','Use dimensional books for projects. List view remains available at any time.')}${settingSwitch('motion','Subtle interface motion','Transitions respect the system’s reduced-motion preference too.')}${S.data.integrated?'<p class="fine">Atelier owns the home and navigation. Change their appearance and compatibility in the Study desk’s Appearance panel.</p>':settingSwitch('show_home','A quiet home-screen entry','Adds one small Workshop link; never replaces Atelier, Sprout, or the deck list.')+settingSwitch('show_toolbar','Card Studio in the top navigation','Tools → Workshop remains available when the link is hidden.')}`}</section><section class="settings-section"><h2>Connected, not crowded.</h2><p>Specialist tools keep their own supported editors and settings.</p>${[['Exam Studio',i.sprout,S.data.integrated?'Build a plan directly from a project’s original linked notes. The exact note scope is retained; you confirm and save the new plan.':'Opens your installed Sprout and copies an exact note filter. You choose the exam and covering decks; no private exam files are edited.'],['Atelier',S.data.integrated||i.atelier,S.data.integrated?'The home, native Add route, editor, repair queue and source links use this one built-in Card Studio. No second authoring controller is needed.':'A small additive home entry uses its existing companion-widget slot. Workshop does not replace the home screen.'],['Native image occlusion',true,'Mask Studio makes grouped native Image Occlusion questions. Existing masks remain editable in their native or owning editor.'],['HyperTTS',i.hypertts,'Open the native Add editor and use HyperTTS’s own toolbar. Workshop does not bypass its presets or consent.'],['Contanki',i.contanki,'The normal reviewer and controller mappings are left alone. Workshop uses full modifier shortcuts, not single-letter review keys.'],['Shared-deck services',i.anki_hub||i.anki_collab,'Recognized managed fields and tags are protected from inline and bulk editing. Use the native editor or upstream suggestion process.']].map(([l,ok,t])=>`<div class="integration-line"><div class="row between"><strong>${l}</strong><span class="pill ${ok?'accent':''}">${ok?'Available':'Not detected'}</span></div><small>${t}</small></div>`).join('')}</section><section class="settings-section"><h2>Optional assistance.</h2><p>Manual creation, search, PDFs, and repairs work without AI. Suggestions and semantic reranking require your own compatible provider and explicit text-sharing approval.</p>${settingSwitch('ai_enabled','Enable provider-assisted features','An OpenAI-compatible chat / embeddings endpoint; a subscription to another app does not supply API access.')}
 <div class="stack" style="margin-top:17px"><label class="field">API base URL<input data-provider="ai_endpoint" value="${E(s.ai_endpoint)}" placeholder="https://provider.example/v1" autocomplete="off"><small>HTTPS for remote providers. Local models may use HTTP on localhost. No provider is selected for you.</small></label><div class="form-grid"><label class="field">Chat model<input data-provider="ai_model" value="${E(s.ai_model)}" autocomplete="off"></label><label class="field">Embedding model<input data-provider="embedding_model" value="${E(s.embedding_model)}" autocomplete="off"></label></div><label class="check"><input type="checkbox" data-provider="remote_consent"${s.remote_consent?' checked':''}><span>Allow approved selections to leave this computer.<small>Every request still shows its exact passage or candidate set before sending. Provider fees and policies apply.</small></span></label><div class="row wrap">${B('save-provider','Save provider settings','check','small')}${B('set-key','Enter API key','key','small')}${B('clear-key','Forget key','close','quiet small')}</div><p class="key-status" id="ws-key-status">${S.keySet?'A key is held in memory for this profile session.':'No key entered in this workspace session.'} Keys are never stored in the library or exports.</p></div></section><section class="settings-section"><h2>Protection & workload.</h2><p>No automatic fact correction, media cleanup, or scheduler changes.</p><div class="stack"><label class="field">Protected field names<input id="ws-protected-fields" value="${E(s.protected_fields.join(', '))}"><small>Comma-separated exact field names. Known service-owned fields are also protected.</small></label><label class="field">Managed-note tag prefixes<input id="ws-protected-tags" value="${E(s.protected_tags.join(', '))}"><small>Notes tagged with these names or their :: subtags use the native editor.</small></label>${B('save-protection','Save protections','shield','small')}<div class="form-grid"><label class="field">Planned new cards per day<input type="number" data-setting="new_per_day" value="${s.new_per_day}" min="1" max="500"></label><label class="field">Estimated seconds per first pass<input type="number" data-setting="seconds_per_card" value="${s.seconds_per_card}" min="5" max="300"></label></div><p class="fine">These are planning assumptions, not Anki settings. Future reviews and actual learning time are not predicted.</p></div></section><section class="settings-section"><h2>Carry your work with you.</h2><p>Export sources, editions, drafts, and source records as a local library archive. Anki’s notes and scheduling remain in Anki.</p><div class="row wrap">${B('export-library','Export library','download','small')}${B('import-library','Import library','upload','small')}${B('capture-guide','Browser capture','globe','small')}</div><p class="fine" style="margin-top:14px">Imports create additional projects. Foreign note links are detached and imported drafts return to unapproved status. No existing collection is overwritten.</p></section></div><aside><section class="panel privacy-card">${I('shield')}<h2>A library that belongs to you.</h2><p>Sources and drafts live in this Anki profile’s <code>workshop</code> folder. API credentials remain in memory.</p><p>Approved cards use normal Anki notes and media, so they remain useful without Workshop. The local source library and its file paths do not automatically synchronize through AnkiWeb.</p><p>No accounts, telemetry, remote fonts, or background collection uploads. Optional provider requests transmit only the text shown in their approval dialog.</p>${B('diagnostics','Open diagnostics','info','small')}<hr><p>Workshop ${E(S.data.version)}<br>Desktop add-on · engineering candidate</p><p>Native Windows and add-on combinations still require acceptance testing. The preview of a card does not execute its scripts here; native Preview does.</p></section></aside></div>`;}
function settingSwitch(key,title,desc){return `<label class="setting-row"><div><strong>${title}</strong><small>${desc}</small></div><input type="checkbox" role="switch" data-setting="${key}"${S.state.settings[key]?' checked':''}></label>`;}
function showModal(title,subtitle,body,footer='',callback=null,wide=false){maskComposer?.dispose();maskComposer=null;const d=$('#ws-dialog');if(!d.open)lastFocus=document.activeElement;S.modal={title};modalCallback=callback;d.dataset.locked='false';d.className=wide?'wide':'';d.innerHTML=`<header class="modal-heading"><div><h2 id="ws-dialog-title">${E(title)}</h2>${subtitle?`<p>${E(subtitle)}</p>`:''}</div>${IB('close-modal','Close dialog','close')}</header><div class="modal-body">${body}</div><footer class="modal-footer">${footer||B('close-modal','Done','','primary small')}</footer>`;if(!d.open)d.showModal();}
function closeModal(){maskComposer?.dispose();maskComposer=null;const d=$('#ws-dialog');d.close();modalCallback=null;S.modal=null;}
function confirm(title,body,callback,label='Continue'){showModal(title,'',`<p class="fine">${E(body)}</p>`,B('close-modal','Cancel','','small')+B('confirm-modal',label,'check','primary small'),callback);}
function projectDialog(id=''){const destination=S.view;const p=id?S.state.projects.find(x=>x.id===id):null;let chosen=p?.cover||'botanical';const body=`<div class="stack"><label class="field">Project title<input id="ws-project-title" value="${E(p?.title||'')}" maxlength="120" autofocus required></label><label class="field">A note about this collection<textarea id="ws-project-description" maxlength="1200">${E(p?.description||'')}</textarea><small>The subject, the goal, or the question you’re exploring.</small></label><div><div class="eyebrow">Choose your binding</div><div class="binding-grid">${Object.entries(coverNames).map(([k,l])=>B('choose-cover',`<span class="binding-sample" data-cover="${k}">${ART.motif(k)}</span><span>${l}</span>`,'','binding-choice',`data-value="${k}" aria-pressed="${k===chosen}"`)).join('')}</div><input id="ws-project-cover" type="hidden" value="${chosen}"></div></div>`;
 showModal(p?'Shape this project.':'A volume of your own.','Sources, drafts, and approved cards share one clear home.',body,B('close-modal','Cancel','','small')+B('confirm-modal',p?'Save project':'Create project','check','primary small'),async()=>{const title=$('#ws-project-title').value,description=$('#ws-project-description').value,cover=$('#ws-project-cover').value;const result=await request('project',{...(p?{id:p.id,revision:p.revision,archived:p.archived}:{}),title,description,cover});closeModal();await refreshState();S.project=result.id;S.view=!p&&['studio','import'].includes(destination)?destination:'project';if(!p){clearSourceContext();if(S.view==='studio')createDraftObject();}render();scrollTop();toast(p?'Project updated.':'Project created. Your sources and drafts will stay together.');});$('#ws-project-title')?.focus();
}
function pasteDialog(sourceId=''){if(!S.project)return projectDialog();const source=sourceId?S.state.sources.find(x=>x.id===sourceId):null;showModal(source?'A revised source.':'Keep the passage, not just the answer.','Text remains local. No extraction or paraphrasing is performed.',`<div class="stack"><label class="field">Source title<input id="ws-source-title" value="${E(source?.title||'')}" maxlength="200"></label><label class="field">Original passage<textarea id="ws-source-text" style="min-height:225px" maxlength="700000"></textarea></label><label class="field">Original URL (optional)<input id="ws-source-url" type="url" value="${E(source?.locator||'')}" maxlength="2000"><small>A reference link only. Workshop does not fetch or scrape the website.</small></label></div>`,B('close-modal','Cancel','','small')+B('confirm-modal',source?'Save new edition':'Add source','source','primary small'),async()=>{const r=await request('source_text',{project_id:S.project,title:$('#ws-source-title').value,text:$('#ws-source-text').value,url:$('#ws-source-url').value,source_id:sourceId});closeModal();await refreshState();await openSource(r.source.id);toast(r.unchanged?'The source is unchanged.':'Original text saved with its edition.');});}
async function importFile(sourceId=''){if(!S.project)return projectDialog();await flushDraft();const result=await request('import_file',{project_id:S.project,source_id:sourceId});if(result.cancelled)return;await refreshState();if(result.errors?.length)showModal('Some sources need attention.','Successful files were kept; failed files were not guessed.',result.errors.map(e=>notice(e.file+': '+e.error,'error')).join(''));if(result.sources?.length){const id=result.sources[0].source.id;await openSource(id);toast(`${result.sources.length} source${result.sources.length===1?'':'s'} imported. Original files stay local.`);}else render();}
function previewDraft(){const d=S.draft;if(!d)return;if(d.kind==='occlusion')return editMaskDraft(true);const q=E(d.front).replace(/\{\{c\d+::([\s\S]*?)(?:::[\s\S]*?)?\}\}/g,'<span class="cloze">[$1]</span>');const src=S.state.sources.find(s=>s.id===d.source_id);showModal('The card, before it joins Anki.','Plain-text draft preview. Custom template rendering uses native Preview after approval.',`<div class="card-preview"><div class="eyebrow" style="color:#6b7d61;margin-bottom:18px">Recall, in your own words</div><div class="preview-question">${q}</div><div id="ws-preview-front-media"></div><div class="preview-answer">${E(d.back)}</div><div id="ws-preview-back-media"></div>${d.context?`<div class="preview-context">${E(d.context)}</div>`:''}${src?`<div class="preview-source">${E(src.title)} · page ${d.page}<br>${E(d.quote)}</div>`:''}</div>${issueList(d.issues)}`,B('close-modal','Keep shaping','','small')+B('preview-save','Save draft','check','primary small'));
 for(const m of d.media)request('image',{blob:m.blob}).then(r=>{const el=$('#ws-preview-'+m.side+'-media');if(!el)return;el.insertAdjacentHTML('beforeend',r.image.startsWith('data:audio')?`<audio controls src="${E(r.image)}" style="max-width:100%;margin-top:15px"></audio>`:`<img class="preview-media" src="${E(r.image)}" alt="${E(m.alt)}">`);}).catch(e=>toast(e.message,true));}
async function startMasks(asset,preview=false){
 await flushDraft();
 const previous=S.draft,frontImage=previous?.media.find(m=>m.side==='front');
 const reuse=previous?.kind==='occlusion'&&frontImage?.blob===asset.blob;
 if(!reuse){
   const deck=previous?.deck_id,tags=previous?.tags?.slice()||[];
   createDraftObject('occlusion');if(deck)S.draft.deck_id=deck;S.draft.tags=tags;
   Object.assign(S.draft,{front:'Recall the hidden labels.',masks:[],hide_others:true,media:[{blob:asset.blob,side:'front',alt:'Occlusion source'}]});
   if(S.source)Object.assign(S.draft,{source_id:S.source.source.id,version_id:S.source.version.id,page:S.page,quote:S.selection||''});
   markDirty();await saveDraft();
 }
 if(!asset.image)asset.image=(await request('image',{blob:asset.blob})).image;
 showModal('Mask Studio','Draw once. Stamp the next label. Group related answers into one question.', '<div id="ws-mask-root"></div>',`<p id="ws-mask-save-status">Draft edits autosave locally. No cards are added until Review & add.</p>`+B('mask-done','Save draft & return','check','primary small'),null,true);
 $('#ws-dialog').classList.add('mask-dialog');
 maskComposer=window.WorkshopMasks.mount($('#ws-mask-root'),{image:asset.image,masks:S.draft.masks||[],hideOthers:S.draft.hide_others!==false,onChange:(masks,hide)=>{
   if(!S.draft||S.draft.kind!=='occlusion')return;S.draft.masks=masks;S.draft.hide_others=hide;markDirty();
 }});
 if(preview)maskComposer.action('preview');
}
async function editMaskDraft(preview=false){
 if(!S.draft)return;
 const media=S.draft.media.find(m=>m.side==='front'&&/\.(png|jpg|jpeg|webp)$/.test(m.blob));
 if(media)return startMasks({blob:media.blob},preview);
 if(S.pageDoc?.image&&S.source){const result=await request('mask_source',{version_id:S.source.version.id,page:S.page});return startMasks(result,preview);}
 throw new Error('Open a PDF page or image, paste a screenshot, or attach an image before creating masks.');
}
async function approve(ids){await flushDraft();if(!ids?.length)throw new Error('Select at least one saved draft in the tray.');if(ids.length>100)throw new Error('Approve at most 100 drafts in one batch.');const data=await request('preflight',{draft_ids:ids});let estimate=await request('workload',{cards:data.total_cards,daily:S.state.settings.new_per_day,seconds:S.state.settings.seconds_per_card});
 const body=`${notice(data.notice)}<div class="summary-strip" style="margin:17px 0;grid-template-columns:repeat(3,1fr)"><div class="summary-number"><strong>${data.notes}</strong><span>new notes to approve</span></div><div class="summary-number"><strong>${data.total_cards}</strong><span>potential new cards</span></div><div class="summary-number"><strong>${Math.ceil(data.total_cards/S.state.settings.new_per_day)}</strong><span>days to introduce at your pace</span></div></div><p class="fine">First-pass time: approximately ${Math.ceil(data.total_cards*S.state.settings.seconds_per_card/60)} minutes, using your explicit time-per-card assumption. Subsequent reviews are additional.</p>${data.items.map(row=>`<section class="approval-item"><div class="approval-meta"><span class="pill">${E(row.deck_name)}</span><span class="pill">${E(row.model_name)}</span><span class="pill">${count(row.estimated_cards,'card')}${row.conditional_templates?' (up to)':''}</span></div><h3>${E(row.draft.front)}</h3>${row.draft.kind==='occlusion'?notice(`${row.draft.masks.length} masks in ${row.estimated_cards} native questions. ${row.draft.hide_others?'Other answers stay covered.':'Other answer regions remain visible.'} The original image is stored once.`):''}<p class="fine pre">${E(row.draft.back)}</p>${row.draft.quote?`<blockquote>${E(row.draft.quote)}</blockquote>`:''}${issueList(row.issues)}${row.duplicate_scan_partial?notice('Duplicate search reached its 2,000-candidate limit. An equivalent note may remain outside this scan.'):''}${row.exact_duplicates.length||row.batch_duplicate?`<label class="check"><input type="checkbox" data-duplicate="${row.draft.id}"><span>I intend to add this despite matching question wording${row.batch_duplicate?' in another selected draft':''}${row.exact_duplicates.length?' on '+row.exact_duplicates.length+' existing note(s)':''}.</span></label>`:''}${row.existing_marker.length?notice('This draft was already added before local bookkeeping finished. Its existing note will be relinked, not added again.'):''}</section>`).join('')}<label class="check"><input type="checkbox" id="ws-approve-check"><span>I checked the questions, answers, source passages, destinations, and card counts.<small>This approves new Anki notes. It does not answer or reschedule existing cards.</small></span></label>`;
 showModal('Ready to enter your collection?','Every proposed note, in one explicit approval.',body,B('close-modal','Keep reviewing','','small')+B('confirm-modal','Add approved notes','check','primary small'),async()=>{if(!$('#ws-approve-check').checked)throw new Error('Confirm that you reviewed this batch before adding it.');const duplicates=$$('[data-duplicate]:checked').map(x=>x.dataset.duplicate);const r=await request('commit',{token:data.token,approved:true,allow_duplicates:duplicates});S.selectedDrafts.clear();if(S.draft&&ids.includes(S.draft.id)){S.draft=null;S.dirty=false;}closeModal();await refreshState();render();toast(`${r.added} notes added${r.reconciled?' · '+r.reconciled+' existing notes relinked':''}. Their scheduling remains Anki’s.`);if(r.warnings?.length)showModal('Cards added; a record needs attention.','Do not recreate the same draft.',r.warnings.map(x=>notice(x,'error')).join(''));},true);
