 if(a==='discard-draft'){const d=S.state.drafts.find(x=>x.id===b.dataset.id);if(!d)return;showModal('Discard this draft?','',`<p>This removes the unapproved draft, not any Anki cards. The source document stays in your library.</p><div class="excerpt">${E(d.front||'Unwritten question')}</div>`,B('close-modal','Keep draft','','small')+B('confirm-modal','Discard draft','trash','primary small'),async()=>{if(S.draft?.id===d.id){clearTimeout(saveTimer);S.draft=null;S.dirty=false;await request('dirty',{value:false});}await request('delete_draft',{id:d.id,revision:d.revision});S.selectedDrafts.delete(d.id);await refreshState();closeModal();render();toast('Unapproved draft discarded. Your source is unchanged.');});return;}

 if(a==='close-modal'){closeModal();return;}
 if(a==='confirm-modal'){
   const callback=modalCallback;if(!callback)return;const d=$('#ws-dialog');d.dataset.locked='true';
   try{await callback();}finally{d.dataset.locked='false';}return;
 }
 if(a==='nav')return navigate(b.dataset.view);
 if(a==='refresh-workspace'){await flushDraft();S.data=await request('load');S.state=S.data.state;render();toast('Library and Anki destinations refreshed.');return;}
 if(a==='new-project'){await flushDraft();return projectDialog();}
 if(a==='edit-project'){await flushDraft();return projectDialog(id);}
 if(a==='choose-cover'){$('#ws-project-cover').value=b.dataset.value;$$('.binding-choice').forEach(x=>x.setAttribute('aria-pressed',String(x===b)));return;}
 if(a==='open-project'){await flushDraft();S.project=id;S.selectedDrafts.clear();S.view='project';render();scrollTop();return;}
 if(a==='archive-project'){const p=project();await request('project',{...p,archived:!p.archived});await refreshState();render();toast(p.archived?'Project returned to your desk.':'Project archived. Sources and Anki notes remain intact.');return;}
 if(a==='library-tab'){S.libraryFilter=b.dataset.value;render();return;}
 if(a==='library-view'){S.libraryList=b.dataset.value==='list';render();return;}
 if(a==='studio-project'){await flushDraft();S.view='studio';if(!S.draft||S.draft.project_id!==S.project){clearSourceContext();createDraftObject();}render();scrollTop();return;}
 if(a==='paste-source')return pasteDialog();
