 if(a==='find-destination'){destinationOptions=S.data.integrated?(await request('suite_decks')).decks:S.data.catalog.decks;destinationQuery='';destinationSort='active';showModal('Choose the Anki destination','Search the full folder path. Nothing is published by choosing a deck.',`<div class="form-grid"><label class="field">Find a deck<input id="ws-destination-query" type="search"></label><label class="field">Sort<select id="ws-destination-sort"><option value="active">Active classes first</option><option value="name">Name A–Z</option></select></label></div><div id="ws-destination-results">${destinationRows()}</div>`,B('close-modal','Cancel','','small'));return;}
 if(a==='pick-destination'){if(!S.draft)return;const d=destinationOptions.find(x=>String(x.id)===id);if(!d)throw new Error('Refresh the deck list.');S.draft.deck_id=Number(d.id);markDirty();closeModal();render();return;}
 if(a==='suite-open'){await flushDraft();return request('suite_open',{view:b.dataset.view||'overview'});}
 if(a==='suite-native'){await flushDraft();return request('suite_native',{command:b.dataset.command});}
 if(a==='paste-image'){if(!S.project)return projectDialog();await flushDraft();const result=await request('clipboard_image',{project_id:S.project});await refreshState();return openSource(result.source.id);}
 if(a==='pdf-layout'){if(!S.source)return;return confirm('Use the exact slide layout.','Choose a PDF exported from this presentation, with one page per slide (including hidden slides). This preserves the PPTX text, notes and figures. Check the first and last page after attaching.',async()=>{const r=await request('pdf_layout',{version_id:S.source.version.id});closeModal();if(!r.cancelled){await openSource(S.source.source.id,S.source.version.id,S.page);toast(r.message);}},'Choose PDF export');}
 if(a==='mask-source'){const r=await request('mask_source',{version_id:S.source.version.id,page:S.page});return startMasks(r);}
