 if(a==='edit-draft'){await flushDraft();const d=S.state.drafts.find(x=>x.id===id);if(!d)throw new Error('Refresh the draft tray.');S.draft=structuredClone(d);S.project=d.project_id;S.view='studio';S.dirty=false;S.matches=[];S.matchRan=false;clearSourceContext();if(d.source_id){S.source=await request('source',{id:d.source_id,version_id:d.version_id});S.page=d.page;S.pageDoc=null;}render();scrollTop();return;}
 if(a==='card-style'&&b.dataset.value==='occlusion')return editMaskDraft();
 if(a==='card-style'){if(!S.draft)createDraftObject(b.dataset.value);S.draft.kind=b.dataset.value;S.draft.model_id=0;S.draft.mapping={};markDirty();render();return;}
