 if(a==='draft-page'){const direction=b.dataset.direction;S.draftPage=Math.max(0,Number(b.dataset.page)||0);$('#ws-inbox-results').innerHTML=inboxResults();($('[data-action="draft-page"][data-direction="'+direction+'"]:not(:disabled)')||$('[data-action="draft-page"]:not(:disabled)'))?.focus();return;}
 if(a==='select-draft-page'){for(const d of visibleDrafts().slice(S.draftPage*25,(S.draftPage+1)*25))S.selectedDrafts.add(d.id);$('#ws-inbox-results').innerHTML=inboxResults();$('[data-action="select-draft-page"]')?.focus();return;}
 if(a==='approve-inbox')return approve(visibleDrafts().filter(d=>S.selectedDrafts.has(d.id)).map(d=>d.id));
 if(a==='preview-draft'){await flushDraft();await previewDraft();return;}
 if(a==='preview-save'){await saveDraft(true);closeModal();return;}
 if(a==='make-cloze'){
   const input=$('[data-draft="front"]');const start=input.selectionStart,end=input.selectionEnd;
   if(start===end)throw new Error('Select the phrase to hide in the question text first.');const existing=[...input.value.matchAll(/\{\{c(\d+)::/g)].map(m=>Number(m[1]));const next=Math.max(0,...existing)+1;if(next>99)throw new Error('Use at most 99 cloze numbers per note.');input.value=input.value.slice(0,start)+'{{c'+next+'::'+input.value.slice(start,end)+'}}'+input.value.slice(end);S.draft.front=input.value;markDirty();input.focus();return;
 }
 if(a==='use-passage')return usePassage();
 if(a==='toggle-source-mode'){S.sourceMode=S.sourceMode==='text'?'page':'text';S.cropping=false;S.crop=null;render();return;}
 if(a==='page-prev'||a==='page-next'){const n=S.page+(a==='page-prev'?-1:1);if(n<1||n>S.source.version.pages.length)return;S.page=n;S.pageDoc=null;S.selection='';S.crop=null;render();return;}
 if(a==='crop-mode'){S.cropping=!S.cropping;S.crop=null;if(S.cropping)S.sourceMode='page';render();return;}
 if(a==='capture-crop'){const result=await request('crop',{version_id:S.source.version.id,page:S.page,rect:S.crop});return attachmentDialog({...result,source:true});}
 if(a==='open-original')return request('open_original',{version_id:S.source.version.id});
 if(a==='attach-file'){if(!S.project&&S.state.projects.length)S.project=S.state.projects[0].id;if(!S.project)return projectDialog();await flushDraft();const r=await request('media_import');if(!r.cancelled)return attachmentDialog(r);return;}
 if(a==='remove-attachment'){S.draft.media.splice(Number(b.dataset.index),1);markDirty();render();return;}
 if(a==='native-occlusion'){
   await flushDraft();const image=S.draft.media.find(m=>/\.(png|jpg|jpeg|webp)$/.test(m.blob));if(!image)throw new Error('Attach an image or capture a region first.');const d=S.draft;const result=await request('occlude',{project_id:d.project_id,source_id:d.source_id,version_id:d.version_id,page:d.page,quote:d.quote,blob:image.blob,deck_id:d.deck_id});toast(result.message);return;
 }
 if(a==='find-matches'){await flushDraft();const query=S.draft.front||S.selection||S.draft.quote;if(!query.trim())throw new Error('Write a question or select a passage before searching.');const r=await request('search',{query:query.slice(0,2000),mode:'words',limit:8});S.matches=r.results;S.matchRan=true;$('#ws-matches').innerHTML=matchingRows();return;}
 if(a==='link-existing')return linkSelection([nid]);
 if(a==='select-all-drafts'){const ids=S.state.drafts.filter(x=>x.project_id===S.project&&x.status!=='committed').map(x=>x.id);if(ids.every(x=>S.selectedDrafts.has(x)))ids.forEach(x=>S.selectedDrafts.delete(x));else ids.forEach(x=>S.selectedDrafts.add(x));render();return;}
 if(a==='approve-selected')return approve([...S.selectedDrafts].filter(id=>S.state.drafts.some(d=>d.id===id&&d.project_id===S.project)));
 if(a==='approve-project'){const ds=S.state.drafts.filter(d=>d.project_id===S.project&&d.status!=='committed').slice(0,100);return approve(S.selectedDrafts.size?[...S.selectedDrafts].filter(id=>ds.some(d=>d.id===id)):ds.map(d=>d.id));}
 if(a==='browse-project'){const ids=[...new Set(S.state.links.filter(l=>l.project_id===S.project).map(l=>l.note_id))];if(!ids.length)throw new Error('No notes are linked yet.');return nativeAction('browse',null,'nid:'+ids.join(','));}
 if(a==='sprout'){await flushDraft();const r=await request('sprout',{project_id:S.project});if(r.opened==='exam-setup'){toast(r.message);return;}showModal('Your exam scope is on the clipboard.',`${r.notes} original notes · no duplicates`,notice(r.message)+`<div class="notice pre" style="margin-top:15px">${E(r.query)}</div>`);return;}
 if(a==='run-search')return runSearch();
 if(a==='search-all'){S.search.query='';return runSearch();}
 if(a==='search-next')return runSearch(true);
 if(a==='search-scope'){S.search.scope=b.dataset.value;S.search.ran=false;S.search.results=[];render();if(S.search.query)await runSearch();return;}
 if(a==='clear-note-selection'){S.selectedNotes.clear();render();return;}
 if(a==='link-selected')return linkSelection([...S.selectedNotes]);
 if(a==='compare-notes')return compareNotes([...S.selectedNotes]);
 if(a==='open-pair'){const p=S.state.pairs.find(p=>p.id===id);return compareNotes(p.note_ids,id);}
 if(a==='batch-dialog')return batchDialog();
 if(a==='open-note'||a==='repair-open')return openNote(nid,a==='repair-open'?id:'');
 if(a==='preview-note')return nativeAction('preview',nid);
 if(a==='split-note')return splitNote(nid);
 if(a==='flag-note'||a==='flag-scan'){
   const reason=a==='flag-scan'?S.scan.items.find(x=>x.id===nid)?.issues.map(i=>i.message).join(' ').slice(0,500)||'Review this card':'Review this card';await request('flag',{note_id:nid,reason,project_id:S.state.links.find(l=>l.note_id===nid)?.project_id||''});await refreshState();if(S.view==='improve')render();toast('Added to the repair queue. The original card is unchanged.');return;
 }
 if(a==='repair-tab'){S.repairFilter=b.dataset.value;render();return;}
 if(['repair-resolve','repair-dismiss','repair-reopen'].includes(a)){await request('resolve',{id,status:a==='repair-resolve'?'resolved':a==='repair-dismiss'?'dismissed':'open'});closeModal();await refreshState();render();toast(a==='repair-resolve'?'Repair marked resolved.':a==='repair-dismiss'?'Suggestion dismissed without changing the note.':'Repair reopened.');return;}
 if(a==='scan')return scanNotes();
 if(a==='scan-next')return scanNotes(true);
 if(a==='media-search')return findMedia();
 if(a==='media-next')return findMedia(true);
 if(a==='media-references'){const data=await request('media_references',{name:b.dataset.name});showModal('One file, all its references.',b.dataset.name,data.count?`<p class="fine">${count(data.count,'note')} reference this exact filename. Reusing it does not modify them.</p><div class="stack" style="margin-top:15px">${data.note_ids.map(n=>B('open-note','Inspect original note '+n,'eye','small',`data-nid="${n}"`)).join('')}</div>`:notice('No exact references were found by the current media search. This is not permission to delete the file; use Anki’s media checker.'));return;}
 if(a==='reuse-media'){if(!S.project&&S.state.projects.length)S.project=S.state.projects[0].id;const r=await request('media_reuse',{name:b.dataset.name});return attachmentDialog(r);}
 if(a==='ai-drafts')return aiDialog();
 if(a==='semantic')return semanticDialog();
 if(a==='theme'){await updateSettings({theme:b.dataset.value});render();return;}
 if(a==='save-provider'){const values={};$$('[data-provider]').forEach(el=>values[el.dataset.provider]=el.type==='checkbox'?el.checked:el.value);await updateSettings(values);toast('Provider settings saved. No text has been sent.');return;}
 if(a==='set-key'){const r=await request('set_key');S.keySet=r.set;$('#ws-key-status').textContent=r.set?'Key held in memory until this profile closes.':'No provider key held.';return;}
 if(a==='clear-key'){await request('clear_key');S.keySet=false;$('#ws-key-status').textContent='Provider key cleared from memory.';return;}
 if(a==='save-protection'){await updateSettings({protected_fields:$('#ws-protected-fields').value.split(',').map(x=>x.trim()).filter(Boolean),protected_tags:$('#ws-protected-tags').value.split(',').map(x=>x.trim()).filter(Boolean)});toast('Field and managed-tag protections saved.');return;}
 if(a==='export-library'){await flushDraft();const r=await request('export',{kind:'library'});if(!r.cancelled)toast('Local library exported. API keys and collection history are not included.');return;}
 if(a==='export-drafts'){await flushDraft();const r=await request('export',{kind:'drafts',project_id:S.project});if(!r.cancelled)toast(`${r.exported} draft records exported as tab-separated text.`);return;}
 if(a==='import-library'){await flushDraft();const r=await request('import_library');if(!r.cancelled){await refreshState();render();toast(`${r.projects} additional projects imported. ${r.detached_links} foreign note links were not adopted.`);}return;}
 if(a==='capture-guide')return captureGuide();
 if(a==='undo'){await flushDraft();const r=await request('undo');await refreshState();if(S.draft?.id){const d=S.state.drafts.find(x=>x.id===S.draft.id);S.draft=d||null;}render();toast('The latest Workshop collection change was undone. Source files and media copies are kept.');return;}
 if(a==='native')return nativeAction(b.dataset.native,nid||null);
 if(a==='diagnostics')return request('diagnostics');
 if(a==='command')return commandDialog();
 if(a==='command-run'){const v=b.dataset.value;closeModal();if(v.startsWith('native-'))return nativeAction(v.slice(7));if(names[v])return navigate(v);return doAction({dataset:{action:v}});}
}
function fieldInput(el){
 if(el.dataset.draft&&S.draft){const k=el.dataset.draft;S.draft[k]=el.type==='checkbox'?el.checked:['deck_id','model_id'].includes(k)?Number(el.value):k==='tags'?el.value.trim().split(/\s+/).filter(Boolean):el.value;if(S.draft.origin==='ai'&&['front','back','quote'].includes(k)){S.draft.verified=false;const box=$('[data-draft="verified"]');if(box)box.checked=false;}if(k==='model_id'){S.draft.mapping={};const mapping=$('#ws-field-mapping');if(mapping)mapping.innerHTML=fieldMapping(S.draft);}markDirty();}
 if(el.dataset.mapping&&S.draft){if(el.value)S.draft.mapping[el.dataset.mapping]=el.value;else delete S.draft.mapping[el.dataset.mapping];markDirty();}
 const k=el.dataset.input;
 if(k==='draft-query'){S.draftQuery=el.value;S.draftPage=0;S.selectedDrafts.clear();$('#ws-inbox-results').innerHTML=inboxResults();}
 if(k==='library-query'){S.libraryQuery=el.value;const ps=S.state.projects.filter(p=>(S.libraryFilter==='all'||S.libraryFilter==='archived'&&p.archived||S.libraryFilter==='active'&&!p.archived)&&`${p.title} ${p.description}`.toLowerCase().includes(S.libraryQuery.toLowerCase()));$('#ws-library-results').innerHTML=projectBooks(ps);}
 if(k==='search-query')S.search.query=el.value;
 if(k==='media-query')S.media.query=el.value;
 if(el.id==='ws-command-query'){const q=el.value.toLowerCase();$$('.command-item').forEach(b=>b.hidden=!b.textContent.toLowerCase().includes(q));}
}
async function fieldChange(el){
 if(el.dataset.draft||el.dataset.mapping)fieldInput(el);
 const change=el.dataset.change;
 if(change==='draft-project'){S.draftProject=el.value;S.draftPage=0;S.selectedDrafts.clear();$('#ws-inbox-results').innerHTML=inboxResults();}
 if(change==='import-project'){await flushDraft();S.project=el.value;clearSourceContext();S.draft=null;renderSidebar();}
 if(change==='studio-project'){await flushDraft();S.project=el.value;S.selectedDrafts.clear();clearSourceContext();createDraftObject();render();}
 if(change==='studio-source'){if(el.value)await openSource(el.value);else{clearSourceContext();render();}}
 if(change==='source-version')await openSource(S.source.source.id,el.value,S.page);
 if(change==='page-number'){const n=Number(el.value);if(!Number.isInteger(n)||n<1||n>S.source.version.pages.length)throw new Error('Choose an available source page.');S.page=n;S.pageDoc=null;S.selection='';S.crop=null;render();}
 if(change==='search-deck')S.search.deck_id=Number(el.value);
 const checked=el.dataset.check;
 if(checked==='draft'){el.checked?S.selectedDrafts.add(el.dataset.id):S.selectedDrafts.delete(el.dataset.id);if(S.view==='drafts'){const n=visibleDrafts().filter(d=>S.selectedDrafts.has(d.id)).length;$('#ws-selected-draft-count').textContent=n+' selected';$('[data-action="approve-inbox"]').disabled=!n;}}
 if(checked==='note'){el.checked?S.selectedNotes.add(Number(el.dataset.nid)):S.selectedNotes.delete(Number(el.dataset.nid));const current=$('.bulk-float');if(S.selectedNotes.size){if(current)current.outerHTML=bulkBar();else $('#ws-page').insertAdjacentHTML('beforeend',bulkBar());}else current?.remove();}
 if(checked==='native-search')S.search.mode=el.checked?'anki':'words';
 if(el.dataset.setting){const k=el.dataset.setting;await updateSettings({[k]:el.type==='checkbox'?el.checked:Number(el.value)});if(k==='living_library')S.libraryList=!el.checked;}
}
async function init(){root=document.getElementById('workshop');if(!root)return;bindDestinations();document.documentElement.classList.add('workshop-host');
 root.addEventListener('click',async e=>{
   const site=e.target.closest('[data-site]');if(site){e.preventDefault();request('open_url',{url:site.href}).catch(x=>toast(x.message,true));return;}
   const b=e.target.closest('button[data-action]');if(!b||!root.contains(b)||b.disabled)return;e.preventDefault();if(b.dataset.action==='close-modal'&&$('#ws-dialog').dataset.locked==='true')return;
   b.disabled=true;try{await doAction(b);}catch(err){toast(err.message||'The action could not finish.',true);}finally{if(b.isConnected)b.disabled=false;}
 });
 root.addEventListener('input',e=>{if(e.target.matches('input:not([type="checkbox"]),textarea'))fieldInput(e.target);});
 root.addEventListener('change',async e=>{try{await fieldChange(e.target);}catch(err){toast(err.message,true);}});
 root.addEventListener('submit',async e=>{e.preventDefault();try{if(e.target.id==='ws-search-form')await runSearch();if(e.target.id==='ws-media-form')await findMedia();}catch(err){toast(err.message,true);}});
 root.addEventListener('pointerup',()=>{const selection=window.getSelection();if(!selection||selection.isCollapsed)return;const node=selection.anchorNode,focus=selection.focusNode;const paper=$('#ws-source-paper');if(paper&&paper.contains(node)&&paper.contains(focus)){S.selection=String(selection).slice(0,20000);const el=$('#ws-selection');if(el){el.hidden=false;el.querySelector('span').textContent=S.selection;}}});
 document.addEventListener('keydown',e=>{if((e.ctrlKey||e.metaKey)&&e.key.toLowerCase()==='k'){e.preventDefault();commandDialog();}if((e.ctrlKey||e.metaKey)&&e.key.toLowerCase()==='s'&&S.view==='studio'){e.preventDefault();saveDraft(true).catch(err=>toast(err.message,true));}});
 window.addEventListener('pagehide',()=>window.Workshop.dispose(),{once:true});
 try{S.data=await request('load');S.state=S.data.state;S.keySet=!!S.data.key_set;S.view=names[S.data.initial_view]?S.data.initial_view:'library';S.project=S.state.projects.find(p=>!p.archived)?.id||null;S.libraryList=!S.state.settings.living_library;shell();if(S.view==='studio'&&S.project)createDraftObject();render();if(S.view==='media')await findMedia();if(S.data.initial_note)await openNote(S.data.initial_note);}
 catch(e){root.innerHTML=`<div class="empty-state" style="height:100%">${ART.empty()}<h2>Your library could not open.</h2><p>${E(e.message)}</p><p>Use the native Diagnostics button for details. Your collection has not been replaced.</p></div>`;}
}
if(document.readyState==='loading')document.addEventListener('DOMContentLoaded',init,{once:true});else init();
})();
